export const findAll4QueryKey = (options?: Options<FindAll4Data>) => createQueryKey('findAll4', options);

/**
 * Listar permisos
 *
 * Devuelve todos los permisos registrados en el sistema.
 */
export const findAll4Options = (options?: Options<FindAll4Data>) => queryOptions<FindAll4Response, FindAll4Error, FindAll4Response, ReturnType<typeof findAll4QueryKey>>({
    queryFn: async ({ queryKey, signal }) => {
        const { data } = await findAll4({
            ...options,
            ...queryKey[0],
            signal,
            throwOnError: true
        });
        return data;
    },
    queryKey: findAll4QueryKey(options)
});

